  ARRAY[$q0$konut sigortası su kaçağı$q0$, $q0$dahili su teminatı$q0$, $q0$evde su borusu patladı sigorta$q0$, $q0$komşuya su sızması sigorta$q0$, $q0$konut sigortası tesisat hasarı$q0$]::text[],
